// tests/e2e/onboarding.spec.ts
import { test, expect } from '@playwright/test';

test.describe('Local User Onboarding', () => {
  test.beforeEach(async () => {
    // Reset database to fresh state
    await resetDatabase();
  });

  test('fresh database shows onboarding screen', async ({ page }) => {
    await page.goto('/');
    await expect(page.locator('h1')).toContainText('Welcome to Animo');
    await expect(page.locator('input#displayName')).toBeVisible();
    await expect(page.locator('input#username')).toBeVisible();
  });

  test('completing onboarding creates user and shows main app', async ({ page }) => {
    await page.goto('/');
    await page.fill('#displayName', 'Test User');
    await page.fill('#username', 'testuser');
    await page.click('button[type="submit"]');

    // Should navigate to main app
    await expect(page.locator('[data-testid="app-shell"]')).toBeVisible();

    // Reload should go directly to app
    await page.reload();
    await expect(page.locator('[data-testid="app-shell"]')).toBeVisible();
  });

  test('login and register routes are not accessible', async ({ page }) => {
    await page.goto('/login');
    // Should redirect or show 404
    await expect(page.locator('h1')).not.toContainText('Login');

    await page.goto('/register');
    await expect(page.locator('h1')).not.toContainText('Register');
  });

  test('data operations work after onboarding', async ({ page }) => {
    // Complete onboarding first
    await completeOnboarding(page, 'Test User', 'testuser');

    // Test CRUD operations
    // Create client
    await page.click('[data-testid="add-client"]');
    await page.fill('[name="clientName"]', 'Test Client');
    await page.click('button[type="submit"]');
    await expect(page.locator('[data-testid="client-list"]')).toContainText('Test Client');

    // Similar tests for projects, tags, time entries, reports
  });

  test('theme preference persists', async ({ page }) => {
    await completeOnboarding(page, 'Test User', 'testuser');

    await page.goto('/settings');
    await page.selectOption('[data-testid="theme-select"]', 'dark');

    await page.reload();
    await expect(page.locator('html')).toHaveAttribute('data-theme', 'dark');
  });
});
```

